import{_ as t,b as l,c as o,g as n}from"./chunks/framework.86O3EbG5.js";const p=JSON.parse('{"title":"多智能体决策","description":"","frontmatter":{"title":"多智能体决策","subTitle":"《人工智能现代方法》读书笔记","author":"oasis","date":"2023-04-04T00:00:00.000Z","tags":["AI"]},"headers":[],"relativePath":"articles/artificial-intelligence/books/AI-modern-approach/18.md","filePath":"articles/artificial-intelligence/books/AI-modern-approach/18.md"}'),r={name:"articles/artificial-intelligence/books/AI-modern-approach/18.md"};function s(e,i,a,g,d,c){return l(),o("div",null,[...i[0]||(i[0]=[n('<p>第 18 章是机器学习入门，侧重于监督学习，核心内容包括：</p><h2 id="基本概念" tabindex="-1">基本概念</h2><ul><li><strong>训练集、测试集</strong>、输入特征、输出标签（离散分类 / 连续回归）</li><li><strong>假设空间、归纳偏置</strong>、过拟合与欠拟合</li><li><strong>性能度量</strong>：准确率、精确率、召回率、F1、均方误差等</li></ul><h2 id="决策树学习" tabindex="-1">决策树学习</h2><ul><li><strong>ID3 算法</strong>：信息增益、熵、递归划分</li><li><strong>剪枝方法</strong>：预剪枝（提前停止）、后剪枝（减小错误率）</li><li>处理连续属性、缺失值</li></ul><h2 id="线性模型" tabindex="-1">线性模型</h2><ul><li><strong>线性回归</strong>：最小二乘法、正规方程、梯度下降</li><li><strong>逻辑回归</strong>：sigmoid 函数、交叉熵损失、极大似然估计</li></ul><h2 id="模型评估与选择" tabindex="-1">模型评估与选择</h2><ul><li><strong>交叉验证</strong>（k 折）、留一法</li><li><strong>偏差-方差分解</strong>：偏差（欠拟合）、方差（过拟合）</li><li>模型复杂度选择（正则化：L1、L2）</li></ul><h2 id="支持向量机-svm" tabindex="-1">支持向量机（SVM）</h2><ul><li>最大化间隔、核技巧（第 18 章可能仅介绍概念）</li></ul><h2 id="集成学习" tabindex="-1">集成学习</h2><ul><li><strong>袋装法（Bagging）</strong>、<strong>提升法（Boosting）</strong>、<strong>随机森林</strong></li></ul>',13)])])}const u=t(r,[["render",s]]);export{p as __pageData,u as default};
